class Solution {
    public int minSteps(int n) {
        int result = 0;
        for (int d = 2; d * d <= n; d++) {
            while (n % d == 0) {
                result += d;
                n /= d;
            }
        }
        if (n > 1) result += n;
        return result;
    }
}
